    # Uniform lines in the background color are ordinary empty rows/columns,
    # not dividers. The separator is a uniform line in a different color.
    sep_rows = [r for r in range(1, h - 1)
                if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(1, w - 1)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    row_bounds = [-1] + sep_rows + [h]
